using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Reflection;
using System.Runtime.InteropServices;
using System.Text;
using System.Threading;
using System.Web.Script.Serialization;
using System.Windows.Forms;

// Run through TestDesktopRunner with the production manifest and exe.config.
// Messages target only this fixture's RichEdit HWND. Space characters must be
// generated by Application.Run/TranslateMessage, never posted by the fixture.
internal static class TestQuickNoteInput {
    sealed class Sample { internal long Sent, Dispatched, Changed; }
    sealed class MessageProbe : NativeWindow {
        internal Action<Message> Received;
        internal MessageProbe(IntPtr handle) { AssignHandle(handle); }
        protected override void WndProc(ref Message message) {
            if (Received != null) Received(message);
            base.WndProc(ref message);
        }
    }
    [DllImport("user32.dll", CharSet = CharSet.Unicode, SetLastError = true)]
    [return: MarshalAs(UnmanagedType.Bool)]
    static extern bool PostMessage(IntPtr hwnd, uint message, IntPtr wparam, IntPtr lparam);
    static readonly object gate = new object();
    static readonly List<object> results = new List<object>();
    static ApplicationContext context;
    static Control dispatch;
    static QuickNoteWindow window;
    static QuickNoteStore store;
    static RichTextBox editor;
    static MessageProbe probe;
    static System.Windows.Forms.Timer control;
    static System.Windows.Forms.Timer deadline;
    static System.Threading.Timer producer;
    static string root, expected;
    static int language, sent, dispatched, changed, postErrors, assertions, spaceDown, spaceUp, spaceChars;
    static Sample[] samples;
    static long phaseStarted, allChanged;
    static bool measuring, checkingCancellation, failed, allFast = true;
    static double latencyLimit = 20;
    static string CaseName() { return language == 0 ? "English" : language == 1 ? "Chinese BMP Unicode" : "Mixed English/Chinese with Space keys"; }
    static bool PostSpace(IntPtr target) {
        bool down = PostMessage(target, 0x100, new IntPtr(0x20), new IntPtr(0x00390001));
        bool up = PostMessage(target, 0x101, new IntPtr(0x20), new IntPtr(unchecked((int)0xc0390001)));
        return down && up;
    }
    static double Milliseconds(long ticks) { return ticks * 1000d / Stopwatch.Frequency; }
    static void Check(bool value, string message) { assertions++; if (!value) throw new Exception(message); }
    static double P(List<double> values, double fraction) {
        if (values.Count == 0) return 0;
        values.Sort(); return values[Math.Min(values.Count - 1, (int)(values.Count * fraction))];
    }
    static object Stats(List<double> values) { return new { actual_count = values.Count, p50_ms = P(values, .5), p95_ms = P(values, .95), max_ms = P(values, 1) }; }
    static string Text() { return window.ReadMarkdown(); }
    static void Fail(Exception error) {
        if (failed) return; failed = true;
        Console.Error.WriteLine(error); Environment.ExitCode = 1;
        if (producer != null) producer.Dispose(); producer = null;
        if (control != null) control.Stop();
        if (deadline != null) deadline.Stop();
        if (probe != null) { probe.ReleaseHandle(); probe = null; }
        context.ExitThread();
    }
    static void BeginLanguage() {
        try {
            string seed = language == 0 ? "abcdefghijklmnopqrstuvwxyz" : language == 1 ? "这是听记输入回归测试，中文文字和标点应完整保存。" : " a中b";
            var text = new StringBuilder(); for (int i = 0; i < 80; i++) text.Append(seed[i % seed.Length]); expected = text.ToString();
            string vault = Path.Combine(root, "vault"); Directory.CreateDirectory(vault);
            store = new QuickNoteStore(vault, "sample-" + language, Path.Combine(root, "recovery"));
            window = new QuickNoteWindow(store, Path.Combine(root, "state-" + language));
            editor = (RichTextBox)typeof(QuickNoteWindow).GetField("editor", BindingFlags.Instance | BindingFlags.NonPublic).GetValue(window);
            Check(editor != null && editor.Parent != null, "The production control must be the real native quick-note editor.");
            window.Toggle(); phaseStarted = Stopwatch.GetTimestamp();
            control = new System.Windows.Forms.Timer { Interval = 25 };
            control.Tick += delegate {
                try {
                    if (producer == null) {
                        Check(Milliseconds(Stopwatch.GetTimestamp() - phaseStarted) < 8000, "The fixture must load and handle cancelled input.");
                        if (checkingCancellation) return;
                        if (editor.ReadOnly || Milliseconds(Stopwatch.GetTimestamp() - phaseStarted) < 350) return;
                        StartInput(); return;
                    }
                    bool done; lock (gate) done = changed == 80 && Milliseconds(Stopwatch.GetTimestamp() - allChanged) > 250;
                    if (done) FinishInput();
                    else Check(Milliseconds(Stopwatch.GetTimestamp() - phaseStarted) < 12000, "All directed characters must arrive before timeout.");
                } catch (Exception error) { Fail(error); }
            };
            control.Start();
        } catch (Exception error) { Fail(error); }
    }
    // Check after the complete native message and any generated WM_CHAR return.
    // Native RichEdit has no WPF dispatcher scope or priority to restore.
    static void AfterMessages(Action done) {
        var timer = new System.Windows.Forms.Timer { Interval = 40 };
        timer.Tick += delegate {
            timer.Stop(); timer.Dispose();
            try { done(); } catch (Exception error) { Fail(error); }
        };
        timer.Start();
    }
    static void StartInput() {
        Check(Text() == "", "Each input case starts with an empty note.");
        editor.Focus(); Check(editor.Focused, "The fixture editor must own keyboard focus.");
        Check(editor.IsHandleCreated, "The native RichEdit must expose its own fixture HWND.");
        checkingCancellation = true;
        KeyPressEventHandler cancel = null;
        cancel = delegate(object sender, KeyPressEventArgs args) {
            args.Handled = true; editor.KeyPress -= cancel;
            AfterMessages(delegate {
                Check(Text() == "", "A character cancelled in KeyPress must never be inserted.");
                CheckCancelledSpace();
            });
        };
        editor.KeyPress += cancel;
        Check(PostMessage(editor.Handle, 0x102, new IntPtr('x'), new IntPtr(1)), "The cancelled fixture character must post.");
    }
    static void CheckCancelledSpace() {
        KeyEventHandler cancel = null;
        cancel = delegate(object sender, KeyEventArgs args) {
            if (args.KeyCode != Keys.Space) return;
            args.SuppressKeyPress = true; args.Handled = true; editor.KeyDown -= cancel;
            AfterMessages(delegate {
                Check(Text() == "", "A Space key cancelled in KeyDown must never be inserted.");
                checkingCancellation = false; StartMeasuredInput();
            });
        };
        editor.KeyDown += cancel;
        Check(PostSpace(editor.Handle), "The cancelled fixture Space KeyDown and KeyUp must post.");
    }
    static void StartMeasuredInput() {
        sent = dispatched = changed = postErrors = spaceDown = spaceUp = spaceChars = 0;
        allChanged = 0; samples = new Sample[80]; measuring = true;
        probe = new MessageProbe(editor.Handle);
        probe.Received = delegate(Message message) {
            long received = Stopwatch.GetTimestamp();
            if (!measuring) return;
            try {
                lock (gate) {
                    if (message.Msg == 0x100 && message.WParam.ToInt32() == 0x20) spaceDown++;
                    if (message.Msg == 0x101 && message.WParam.ToInt32() == 0x20) spaceUp++;
                    if (message.Msg != 0x102) return;
                    Check(dispatched < samples.Length && samples[dispatched] != null, "Every WM_CHAR must map to an outstanding fixture input.");
                    Check(message.WParam.ToInt32() == expected[dispatched], "The real HWND must receive exactly the expected character.");
                    if (message.WParam.ToInt32() == 0x20) spaceChars++;
                    samples[dispatched++].Dispatched = received;
                }
            } catch (Exception error) { measuring = false; dispatch.BeginInvoke((Action)delegate { Fail(error); }); }
        };
        editor.TextChanged += Changed;
        IntPtr target = editor.Handle;
        Console.WriteLine("START case=" + CaseName() + "; dpi=" + window.DeviceDpi + "; limit=" + latencyLimit + "ms");
        producer = new System.Threading.Timer(delegate {
            lock (gate) {
                if (!measuring || sent >= samples.Length) return;
                int index = sent++; samples[index] = new Sample { Sent = Stopwatch.GetTimestamp() };
                if (expected[index] == ' ') { if (!PostSpace(target)) postErrors++; }
                else if (!PostMessage(target, 0x102, new IntPtr(expected[index]), new IntPtr(1))) postErrors++;
            }
        }, null, 32, 32);
    }
    static void Changed(object sender, EventArgs args) {
        long timestamp = Stopwatch.GetTimestamp();
        lock (gate) if (measuring) {
            if (changed < samples.Length) samples[changed].Changed = timestamp;
            changed++;
            if (changed == samples.Length) allChanged = timestamp;
        }
    }
    static void FinishInput() {
        measuring = false; control.Stop(); control.Dispose(); control = null;
        producer.Dispose(); producer = null; probe.ReleaseHandle(); probe = null; editor.TextChanged -= Changed;
        Check(sent == 80 && dispatched == 80 && changed == 80 && postErrors == 0, "Exactly 80 targeted inputs must dispatch and change text in " + CaseName() + ".");
        Check(Text() == expected, "Typing must preserve every character in order.");
        int expectedSpaces = language == 2 ? 20 : 0;
        Check(spaceDown == expectedSpaces && spaceUp == expectedSpaces && spaceChars == expectedSpaces,
            "Each posted Space KeyDown/KeyUp pair must naturally generate exactly one WM_CHAR; the fixture never posts a Space character.");
        var spaceLatency = new List<double>(); var characterLatency = new List<double>();
        var latency = new List<double>(); var queue = new List<double>(); var intervals = new List<double>();
        var raw = new List<object>(); long previous = 0; int sampleIndex = 0;
        foreach (Sample sample in samples) {
            Check(sample.Changed >= sample.Dispatched && sample.Dispatched >= sample.Sent, "Every input timestamp must be ordered.");
            bool space = expected[sampleIndex] == ' ';
            double elapsed = Milliseconds(sample.Changed - sample.Dispatched);
            if (space) spaceLatency.Add(elapsed); else characterLatency.Add(elapsed);
            latency.Add(elapsed); queue.Add(Milliseconds(sample.Dispatched - sample.Sent));
            if (previous != 0) intervals.Add(Milliseconds(sample.Sent - previous)); previous = sample.Sent;
            raw.Add(new { input_case = CaseName(), character_index = sampleIndex, code_point = (int)expected[sampleIndex], latency_origin = "RichEdit WM_CHAR receipt", character_source = space ? "TranslateMessage from Space KeyDown" : "fixture-directed Unicode WM_CHAR", sent_ticks = sample.Sent, dispatched_ticks = sample.Dispatched, text_changed_ticks = sample.Changed });
            sampleIndex++;
        }
        object summary = new { language = CaseName(), actual_count = changed, space_key_down = spaceDown, space_key_up = spaceUp, translated_space_characters = spaceChars, latency_origin = "RichEdit WM_CHAR receipt", space_dispatch_to_changed = Stats(spaceLatency), character_dispatch_to_changed = Stats(characterLatency), dispatch_to_text_changed = Stats(latency), post_to_dispatch = Stats(queue), actual_send_interval = Stats(intervals) };
        results.Add(new { summary = summary, stopwatch_frequency = Stopwatch.Frequency, event_ticks = raw });
        Console.WriteLine(new JavaScriptSerializer().Serialize(summary));
        File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "quick-note-input-report.json"), new JavaScriptSerializer().Serialize(results), new UTF8Encoding(false));
        Check(editor.CanUndo, "Real directed typing must remain undoable."); editor.Undo();
        Check(Text() != expected, "Undo must change the typed document.");
        Check(editor.CanRedo, "Typed content must remain redoable."); editor.Redo();
        Check(Text() == expected, "Redo must restore the exact typed document.");
        allFast = allFast && P(latency, .95) < latencyLimit && P(spaceLatency, .95) < latencyLimit;
        CheckHandledAndReadOnlyInput(delegate {
            Action closed = delegate {
                try {
                    Check(window.IsDisposed, "The close continuation runs after disposal.");
                    Check(store.Load(DateTime.Today).Text == expected, "Closing must durably save exact input after Undo/Redo.");
                    language++;
                    if (language < 3) BeginLanguage();
                    else {
                        Console.WriteLine("Content safety assertions passed=" + assertions + " for English, Chinese BMP Unicode and mixed Space-key input.");
                        Check(allFast, "Input p95 WM_CHAR-to-TextChanged must remain below " + latencyLimit + "ms in every case, including translated Space.");
                        Console.WriteLine("PASS assertions=" + assertions + "; three exact native input cases, 20 translated Space keys, cancellation, read-only input, Undo/Redo and durable close."); context.ExitThread();
                    }
                } catch (Exception error) { Fail(error); }
            };
            if (window.FlushAndClose(closed)) closed();
        });
    }
    static void CheckHandledAndReadOnlyInput(Action done) {
        KeyPressEventHandler handled = null;
        handled = delegate(object sender, KeyPressEventArgs args) {
            args.Handled = true; editor.KeyPress -= handled;
            AfterMessages(delegate {
                Check(Text() == expected, "Handled native character input must not insert text.");
                KeyEventHandler handledSpace = null;
                handledSpace = delegate(object keySender, KeyEventArgs key) {
                    if (key.KeyCode != Keys.Space) return;
                    key.Handled = true; key.SuppressKeyPress = true; editor.KeyDown -= handledSpace;
                    AfterMessages(delegate {
                        Check(Text() == expected, "Handled native Space input must not insert text.");
                        editor.ReadOnly = true;
                        Check(PostMessage(editor.Handle, 0x102, new IntPtr('x'), new IntPtr(1)) && PostSpace(editor.Handle), "Read-only character and Space messages must post.");
                        AfterMessages(delegate {
                            Check(Text() == expected, "Read-only native character and Space input must not edit the document.");
                            editor.ReadOnly = false; done();
                        });
                    });
                };
                editor.KeyDown += handledSpace;
                Check(PostSpace(editor.Handle), "The handled fixture Space pair must post.");
            });
        };
        editor.KeyPress += handled;
        Check(PostMessage(editor.Handle, 0x102, new IntPtr('x'), new IntPtr(1)), "The handled fixture character must post.");
    }
    [STAThread] static int Main(string[] args) {
        for (int i = 0; i < args.Length; i++) if (args[i] == "--latency-limit" && i + 1 < args.Length)
            latencyLimit = double.Parse(args[++i], System.Globalization.CultureInfo.InvariantCulture);
        Application.EnableVisualStyles(); Application.SetCompatibleTextRenderingDefault(false);
        root = Path.Combine(Path.GetTempPath(), "tingji-input-" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(root); context = new ApplicationContext(); dispatch = new Control(); IntPtr ignored = dispatch.Handle;
        deadline = new System.Windows.Forms.Timer { Interval = 100 };
        deadline.Tick += delegate {
            if (phaseStarted != 0 && Milliseconds(Stopwatch.GetTimestamp() - phaseStarted) > 15000)
                Fail(new TimeoutException("The input, cancellation, read-only and durable-close callbacks must all finish within the isolated case timeout."));
        };
        deadline.Start();
        dispatch.BeginInvoke((Action)BeginLanguage); Application.Run(context);
        deadline.Stop(); deadline.Dispose();
        if (window != null) window.Dispose(); dispatch.Dispose(); context.Dispose();
        string full = Path.GetFullPath(root), parent = Path.GetFullPath(Path.GetTempPath()).TrimEnd(Path.DirectorySeparatorChar) + Path.DirectorySeparatorChar;
        if (full.StartsWith(parent, StringComparison.OrdinalIgnoreCase) && Path.GetFileName(full).StartsWith("tingji-input-", StringComparison.Ordinal))
            try { Directory.Delete(full, true); } catch { }
        return Environment.ExitCode;
    }
}
